CONTROLS={'ambiguous-without-override': {'build.omg': 'machine build(builder: &mut Build) {\n    Build::application(builder, "case_where_equality_target_body");\n    Build::bind(builder, windows_x86_64::ProgramEntry, entry_start);\n    Build::bind(builder, linux_x86_64::ProgramEntry, entry_start);\n    Build::bind(builder, linux_arm64::ProgramEntry, entry_start);\n    Build::bind(builder, macos_arm64::ProgramEntry, entry_start);\n    Build::select_provider<PointWidth, SelectedPointWidth>(builder, windows_x86_64);\n    Build::select_provider<PointWidth, SelectedPointWidth>(builder, macos_arm64);\n    Build::select_provider<PointWidth, SelectedPointWidth>(builder, linux_arm64);\n}\n', 'main.omg': "// Case Point(lo, hi) where lo == hi makes hi - lo exact in u64, without a guard or Wrapping.\n// Expected exit: 0\ndata Interval [copy]\n    requires (self in Interval::Empty) || ((self in Interval::Point) && (self.lo == self.hi))\n{\n    case Empty;\n    case Point(lo: u64, hi: u64);\n}\ndata Main { interval: Interval; left_guard: u64; width: u64; right_guard: u64; flag: bool; }\n\nmachine run_main(main: &mut Main) crashes Trap {\n    main.width = 99;\n    main.interval = Interval::Point { lo: 17, hi: 17 };\n    PointWidth::run(main);\n}\n\nboundary trait PointWidth {\n    machine run(main: &mut Main) reaches crashes Trap;\n}\nSelectedPointWidth satisfies PointWidth {\n    machine run(main: &mut Main) reaches crashes Trap {\n\n    transition main.interval {\n        Interval::Point { lo, hi } -> take(lo, hi, main)\n        Interval::Empty -> fail()\n    }\n    machine take(lo: u64, hi: u64, main: &mut Main) {\n        main.width = hi - lo;\n        transition main.width == 0 {\n            true -> pass()\n            _ -> fail()\n        }\n    }\n    machine pass() { }\n    machine fail() { crash Trap; }\n    }\n}\n\n// Observe the caller's original home and adjacent cells after return.\nmachine entry_start() crashes Trap {\n    let mut entry_storage: Main = Main { interval: Interval::Empty {}, left_guard: 101, width: 99, right_guard: 107, flag: false };\n    run_main(&mut entry_storage);\n    transition entry_storage.width == 0 && entry_storage.left_guard == 101 && entry_storage.right_guard == 107 && entry_storage.flag == false {\n        true -> observed()\n        false -> writeback_failed()\n    }\n    machine observed() {}\n    machine writeback_failed() { crash Trap; }\n}\n\nAlternatePointWidth satisfies PointWidth {\n    machine run(main: &mut Main) reaches crashes Trap {\n\n    transition main.interval {\n        Interval::Point { lo, hi } -> take(lo, hi, main)\n        Interval::Empty -> fail()\n    }\n    machine take(lo: u64, hi: u64, main: &mut Main) {\n        main.width = hi - lo;\n        transition main.width == 0 {\n            true -> pass()\n            _ -> fail()\n        }\n    }\n    machine pass() { }\n    machine fail() { crash Trap; }\n    }\n}\n\n"}, 'missing-candidate': {'build.omg': 'machine build(builder: &mut Build) {\n    Build::application(builder, "case_where_equality_target_body");\n    Build::bind(builder, windows_x86_64::ProgramEntry, entry_start);\n    Build::bind(builder, linux_x86_64::ProgramEntry, entry_start);\n    Build::bind(builder, linux_arm64::ProgramEntry, entry_start);\n    Build::bind(builder, macos_arm64::ProgramEntry, entry_start);\n}\n', 'main.omg': "// Case Point(lo, hi) where lo == hi makes hi - lo exact in u64, without a guard or Wrapping.\n// Expected exit: 0\ndata Interval [copy]\n    requires (self in Interval::Empty) || ((self in Interval::Point) && (self.lo == self.hi))\n{\n    case Empty;\n    case Point(lo: u64, hi: u64);\n}\ndata Main { interval: Interval; left_guard: u64; width: u64; right_guard: u64; flag: bool; }\n\nmachine run_main(main: &mut Main) crashes Trap {\n    main.width = 99;\n    main.interval = Interval::Point { lo: 17, hi: 17 };\n    PointWidth::run(main);\n}\n\nboundary trait PointWidth {\n    machine run(main: &mut Main) reaches crashes Trap;\n}\n// Observe the caller's original home and adjacent cells after return.\nmachine entry_start() crashes Trap {\n    let mut entry_storage: Main = Main { interval: Interval::Empty {}, left_guard: 101, width: 99, right_guard: 107, flag: false };\n    run_main(&mut entry_storage);\n    transition entry_storage.width == 0 && entry_storage.left_guard == 101 && entry_storage.right_guard == 107 && entry_storage.flag == false {\n        true -> observed()\n        false -> writeback_failed()\n    }\n    machine observed() {}\n    machine writeback_failed() { crash Trap; }\n}\n"}}
observations=[]
for label,files in CONTROLS.items():
 project=D/label;project.mkdir()
 for name,text in files.items():(project/name).write_text(text)
 failure,review=sample_native_gate.accept_review(str(cli),str(project),producer.target,180);(D/(label+'.review.txt')).write_text(review)
 command=[str(cli),'--build-dir',str(D/(label+'-native')),'--report-file',str(D/(label+'.report.txt')),'--target',producer.target,str(project/'main.omg')]
 if failure:code=None;raw=review;seconds=0
 else:
  started=time.monotonic();r=subprocess.run(command,cwd=ROOT,capture_output=True,text=True,stdin=subprocess.DEVNULL,timeout=120);seconds=time.monotonic()-started;code=r.returncode;raw=r.stdout+r.stderr;(D/(label+'.stdout')).write_text(r.stdout);(D/(label+'.stderr')).write_text(r.stderr)
 expected='no provider is selected for boundary requirement' if label=='missing-candidate' else 'covering provider plans for the selected target'
 locks={}
 for name in ['omega.lock','omega.admissions']:
  p=project/name
  if p.is_file():to=D/(label+'.'+name+'.txt');shutil.copy2(p,to);locks[name]=dict(sha256=h(to),bytes=to.stat().st_size,retained=to.name)
 row=dict(label=label,command=command,returncode=code,phase='review' if failure else 'native realization',seconds=seconds,expected_fragment=expected,runtime_executed=False,passed=bool((failure or code!=0) and expected in raw),inputs={name:dict(text=text,sha256=h(project/name)) for name,text in files.items()},consumed_locks=locks);observations.append(row);save('observations.json',observations)
